import {
  access,
  mkdir,
  readdir,
  readFile,
  rmdir,
  unlink,
  writeFile,
} from "node:fs/promises";
import { join } from "node:path";
import { calculatorCatalog } from "../packages/calculators/src/catalog.generated";

export type WebTopicCatalogEntry = { id: string; slug: string };
export type WebTopicOutput = { path: string; content: string };

const routeHeader =
  "---\n// Generated by scripts/generate-web-topics.ts. Do not edit by hand.";

function validateCatalog(
  catalog: readonly WebTopicCatalogEntry[],
): WebTopicCatalogEntry[] {
  const entries = [...catalog].sort((a, b) => a.id.localeCompare(b.id));
  for (const item of entries) {
    if (
      !/^[a-z][a-z0-9-]*$/.test(item.id) ||
      !/^[a-z][a-z0-9-]*$/.test(item.slug)
    ) {
      throw new Error(`Invalid web topic ID or slug: ${item.id}/${item.slug}`);
    }
  }
  for (const [label, values] of [
    ["ID", entries.map(({ id }) => id)],
    ["slug", entries.map(({ slug }) => slug)],
  ] as const) {
    if (new Set(values).size !== values.length)
      throw new Error(`Duplicate web topic ${label}`);
  }
  return entries;
}

function topicRoute(item: WebTopicCatalogEntry): string {
  const { id, slug } = item;
  return `${routeHeader}
import { calculatorCatalog } from "@open-calculators/calculators";
import { lessonImports } from "@open-calculators/content";
import { calculatorRoute } from "@open-calculators/dom-ui/catalog";
import { LessonArticle, Sidebar } from "@open-calculators/dom-ui/components";
import { presentExample as topicExamplePresenter } from "@open-calculators/dom-ui/topics/${id}/examples";
import { en } from "@open-calculators/i18n";
import { metaDescriptions } from "@open-calculators/i18n/meta";
import { topicMessageImports } from "@open-calculators/i18n/topics";
import { ui } from "@open-calculators/i18n/ui";
import TopicView from "@open-calculators/dom-ui/topics/${id}/view";
import Base from "../../../layouts/Base.astro";
import Breadcrumbs from "../../../components/Breadcrumbs.astro";
import LessonVideo from "../../../components/LessonVideo.astro";

const item = calculatorCatalog.find((candidate) => candidate.id === ${JSON.stringify(id)} && candidate.slug === ${JSON.stringify(slug)});
if (!item) throw new Error("Generated web topic does not match calculator catalog: ${id}/${slug}");
const title = en[item.titleKey] ?? item.id;
const description = en[item.descriptionKey] ?? "";
const metaDescription = metaDescriptions[item.id as keyof typeof metaDescriptions] ?? description;

const loadLesson = lessonImports[item.id as keyof typeof lessonImports];
const loadMessages = topicMessageImports[item.id as keyof typeof topicMessageImports];
const [lessonData, topicMessagesData] = await Promise.all([
  loadLesson?.(),
  loadMessages?.(),
]);

const lesson = lessonData?.lesson;
const messages = {
  ...en,
  ...ui,
  ...(topicMessagesData?.messages ?? {}),
};
---
<Base title={title} description={metaDescription}>
  <div class="oc-app">
    <Sidebar client:load activeId={item.id} />
    <main id="calculator" data-category={item.category}>
      <section class="oc-zone oc-zone-tool">
        <div class="oc-zone-inner">
          <Breadcrumbs calculatorId={item.id} />
          <TopicView
            client:load
            id={item.id}
            title={title}
            description={description}
            messages={messages}
            locale="en-US"
          />
        </div>
      </section>
      {lesson ? (
        <section class="oc-zone oc-zone-learn">
          <div class="oc-zone-inner">
            <LessonVideo id={item.id} locale="en-US" />
            <LessonArticle
              lesson={lesson}
              messages={messages}
              locale="en-US"
              presenter={topicExamplePresenter}
              relatedHref={(id) => calculatorRoute(id as any)}
            />
          </div>
        </section>
      ) : null}
    </main>
  </div>
</Base>
`;
}

export async function generateWebTopics(
  catalog: readonly WebTopicCatalogEntry[],
  webRoot: string,
  domTopicsRoot: string,
): Promise<WebTopicOutput[]> {
  const entries = validateCatalog(catalog);
  const outputs: WebTopicOutput[] = [];
  for (const item of entries) {
    for (const source of ["view.tsx", "adapter.ts", "examples.ts"]) {
      const sourcePath = join(domTopicsRoot, item.id, source);
      await access(sourcePath).catch(() => {
        throw new Error(
          `Missing DOM topic ${source} for ${item.id}: ${sourcePath}`,
        );
      });
    }
    outputs.push({
      path: join(webRoot, "src/pages/calculators", item.slug, "index.astro"),
      content: topicRoute(item),
    });
  }
  return outputs;
}

export async function writeWebTopics(
  outputs: readonly WebTopicOutput[],
  webRoot: string,
  check = false,
): Promise<boolean> {
  let fresh = true;
  for (const { path, content } of outputs) {
    if (check) {
      if ((await readFile(path, "utf8").catch(() => "")) !== content) {
        console.error(`Stale generated file: ${path}`);
        fresh = false;
      }
    } else {
      await mkdir(join(path, ".."), { recursive: true });
      await writeFile(path, content);
    }
  }
  if (!check) {
    const routes = new Set(
      outputs
        .filter(({ path }) => path.endsWith(".astro"))
        .map(({ path }) => path),
    );
    const routeRoot = join(webRoot, "src/pages/calculators");
    for (const entry of await readdir(routeRoot, { withFileTypes: true }).catch(
      () => [],
    )) {
      if (!entry.isDirectory()) continue;
      const path = join(routeRoot, entry.name, "index.astro");
      const content = await readFile(path, "utf8").catch(() => "");
      if (content.startsWith(routeHeader) && !routes.has(path)) {
        await unlink(path);
        await rmdir(join(routeRoot, entry.name)).catch(() => {});
      }
    }
  }
  return fresh;
}

if (import.meta.main) {
  const root = join(import.meta.dir, "..");
  const outputs = await generateWebTopics(
    calculatorCatalog,
    join(root, "apps/web"),
    join(root, "packages/dom-ui/src/topics"),
  );
  const fresh = await writeWebTopics(
    outputs,
    join(root, "apps/web"),
    process.argv.includes("--check"),
  );
  if (!fresh) process.exitCode = 1;
}
